"""E2 arm A: processes generated by small hidden quantum Markov models (HQMMs), with the exact predictive.

An HQMM with Kraus operators {K_y} (one per observation, sum_y K_y^dag K_y = I) emits y with probability
Tr(K_y rho K_y^dag) and updates rho <- K_y rho K_y^dag / p(y). The k-step predictive of a filtered state rho_t is
p(y_{t+k}) = Tr(K_y Phi^{k-1}(rho_t) K_y^dag), with Phi(rho) = sum_y K_y rho K_y^dag.

  * A1 probability clock (Zhao & Jaeger 2010, as specified in Srinivasan, Gordon & Boots 2018, eq. 16):
    2 states, 2 observations, no finite-dimensional HMM represents it exactly; relaxation time 2.71 steps.
  * A2 weakly measured qutrit clock: Lueders instrument of strength eps on a qutrit rotated by exp(-i 0.6 H),
    H = F diag(0, 1, sqrt 2) F^dag (F = 3-point Fourier matrix); eps = 0.3271 gives relaxation time 20 steps.

Protocol as T1: start from the stationary state, context L_CTX = 32 observations, then predict k steps ahead.
"""
from __future__ import annotations

from dataclasses import dataclass

import numpy as np
import scipy.linalg as sl

L_CTX = 32


@dataclass(frozen=True)
class HQMMProcess:
    name: str
    K: tuple                      # Kraus operators, one (d, d) complex array per observation

    @property
    def d(self):
        return self.K[0].shape[0]

    @property
    def O(self):
        return len(self.K)

    def channel(self, rho):
        return sum(k @ rho @ k.conj().T for k in self.K)

    def stationary(self):
        sup = sum(np.kron(k, k.conj()) for k in self.K)            # row-major vec: vec(K r K^dag) = (K kron conj K) vec(r)
        w, v = np.linalg.eig(sup)
        r = v[:, np.argmin(np.abs(w - 1))].reshape(self.d, self.d)
        r = 0.5 * (r + r.conj().T)
        return r / np.trace(r).real

    def relaxation_time(self):
        sup = sum(np.kron(k, k.conj()) for k in self.K)
        e = np.sort(np.abs(np.linalg.eigvals(sup)))[::-1]
        return float(-1 / np.log(e[1]))


def probability_clock() -> HQMMProcess:
    c, s = np.cos(0.6), np.sin(0.6)
    K1 = np.array([[0.6 * c, -s], [0.6 * s, c]], dtype=complex)
    K2 = np.array([[0.8, 0], [0, 0]], dtype=complex)
    return HQMMProcess("A1-probability-clock", (K1, K2))


QUTRIT_EPS = 0.3271


def qutrit_clock(eps: float = QUTRIT_EPS, theta: float = 0.6) -> HQMMProcess:
    d = 3
    F = np.exp(2j * np.pi * np.outer(np.arange(d), np.arange(d)) / d) / np.sqrt(d)
    U = sl.expm(-1j * theta * (F @ np.diag([0, 1, np.sqrt(2)]) @ F.conj().T))
    Ks = []
    for y in range(d):
        E = (1 - eps) * np.eye(d) / d
        E[y, y] += eps
        Ks.append(sl.sqrtm(E) @ U)
    return HQMMProcess(f"A2-qutrit-clock(eps={eps:g})", tuple(Ks))


def sample(p: HQMMProcess, n: int, horizon: int, rng: np.random.Generator):
    """n sequences of L_CTX + horizon observations from the stationary state; actions are all zero (one action)."""
    T = L_CTX + horizon
    obs = np.zeros((n, T), dtype=np.int64)
    rho = np.repeat(p.stationary()[None], n, axis=0)
    Ks = np.stack(p.K)                                              # (O, d, d)
    for t in range(T):
        post = np.einsum("yij,njk,ylk->nyil", Ks, rho, Ks.conj())   # unnormalised posteriors per outcome
        pr = np.clip(np.einsum("nyii->ny", post).real, 0, None)
        pr /= pr.sum(1, keepdims=True)
        y = (rng.random(n)[:, None] > np.cumsum(pr, 1)).sum(1).clip(0, p.O - 1)
        obs[:, t] = y
        rho = post[np.arange(n), y] / pr[np.arange(n), y][:, None, None]
    return obs, np.zeros_like(obs)


def exact_predictive(p: HQMMProcess, obs: np.ndarray, K: int) -> np.ndarray:
    """Filter the context exactly, then p(y_{t+k}) for k = 1..K. Returns (n, K, O)."""
    n = obs.shape[0]
    Ks = np.stack(p.K)
    rho = np.repeat(p.stationary()[None], n, axis=0)
    for t in range(L_CTX):
        y = obs[:, t]
        r = np.einsum("nij,njk,nlk->nil", Ks[y], rho, Ks[y].conj())
        rho = r / np.einsum("nii->n", r).real[:, None, None]
    out = np.zeros((n, K, p.O))
    for k in range(K):
        out[:, k] = np.einsum("yij,njk,yik->ny", Ks, rho, Ks.conj()).real
        rho = np.einsum("yij,njk,ylk->nil", Ks, rho, Ks.conj())
    return np.clip(out, 0, None) / np.clip(out, 0, None).sum(-1, keepdims=True)
